import React, { useState } from 'react';
import {
  Activity, AlertCircle, AlertTriangle, ArrowDownRight, ArrowUpRight, Bell, Boxes,
  BrainCircuit, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronRight,
  ClipboardList, Clock3, CreditCard, Download, Edit3, FileBarChart, FileClock, FileText,
  Filter, LayoutDashboard, LogOut, Menu, MoreHorizontal, Package, PackagePlus, Plus, QrCode,
  RotateCcw, Search, Send, Settings as SettingsIcon, ShieldCheck, SlidersHorizontal,
  Stethoscope, Trash2, Truck, UserCheck, UserCog, Users, X,
} from 'lucide-react';

type Page = 'dashboard'|'inventory'|'add-stock'|'expiry'|'dispensing'|'audit'|'customers'|'alerts'|'suppliers'|'recall'|'ai'|'reports'|'settings'|'admin'|'users'|'system-audit';
type Status = 'Available'|'Near Expiry'|'Recalled'|'Low Stock'|'Expired';
type Medicine = { id:number; medicine:string; batch:string; expiry:string; quantity:number; supplier:string; status:Status };
type Audit = { id:number; date:string; medicine:string; batch:string; quantity:number; customer:string; pharmacist:string; status:string };

const initialInventory: Medicine[] = [
  { id:1, medicine:'Paracetamol 500mg', batch:'PCT101', expiry:'Sep 2026', quantity:120, supplier:'ABC Pharma', status:'Available' },
  { id:2, medicine:'Vitamin D3 60K', batch:'VD102', expiry:'Sep 2026', quantity:180, supplier:'HealthCare Labs', status:'Near Expiry' },
  { id:3, medicine:'Amoxicillin 500mg', batch:'AMX204', expiry:'Oct 2026', quantity:45, supplier:'MediSource', status:'Recalled' },
  { id:4, medicine:'Cetirizine 10mg', batch:'CTZ302', expiry:'Jan 2027', quantity:320, supplier:'Nova Pharma', status:'Available' },
  { id:5, medicine:'Azithromycin 250mg', batch:'AZI109', expiry:'Nov 2026', quantity:68, supplier:'MediSource', status:'Low Stock' },
  { id:6, medicine:'Metformin 500mg', batch:'MET501', expiry:'Mar 2027', quantity:410, supplier:'ABC Pharma', status:'Available' },
];
const customers = ['Rahul Kumar','Priya Sharma','Arun Kumar','Kavya S','Meena Devi'];
const nav = [
  { id:'dashboard', label:'Dashboard', icon:LayoutDashboard }, { id:'inventory', label:'Inventory', icon:Boxes },
  { id:'add-stock', label:'Add Stock', icon:PackagePlus }, { id:'expiry', label:'Batch & Expiry', icon:CalendarDays },
  { id:'dispensing', label:'Dispensing', icon:CreditCard }, { id:'audit', label:'Audit', icon:ClipboardList },
  { id:'customers', label:'Customers', icon:Users }, { id:'alerts', label:'Alerts', icon:Bell, count:3 },
  { id:'suppliers', label:'Suppliers & Returns', icon:Truck }, { id:'recall', label:'Batch Recall', icon:RotateCcw },
  { id:'ai', label:'AI Assistant', icon:BrainCircuit }, { id:'reports', label:'Reports', icon:FileBarChart },
  { id:'settings', label:'Settings', icon:SettingsIcon },
];
const adminNav = [{ id:'admin', label:'Admin Dashboard', icon:ShieldCheck },{ id:'users', label:'Users', icon:UserCog },{ id:'system-audit', label:'System Audit', icon:FileClock }];

type Role = 'Administrator' | 'Pharmacist';
function App() {
  const [loggedIn, setLoggedIn] = useState(false);
  const [role, setRole] = useState<Role>('Pharmacist');
  const [page, setPage] = useState<Page>('dashboard');
  const [inventory, setInventory] = useState(initialInventory);
  const [audits, setAudits] = useState<Audit[]>([
    {id:1,date:'Today, 10:42 AM',medicine:'Paracetamol 500mg',batch:'PCT101',quantity:12,customer:'Priya Sharma',pharmacist:'Dr. Anita Rao',status:'Completed'},
    {id:2,date:'Today, 09:18 AM',medicine:'Cetirizine 10mg',batch:'CTZ302',quantity:5,customer:'Arun Kumar',pharmacist:'Dr. Anita Rao',status:'Completed'},
    {id:3,date:'Yesterday, 04:35 PM',medicine:'Vitamin D3 60K',batch:'VD102',quantity:10,customer:'Meena Devi',pharmacist:'Dr. Suresh',status:'Completed'},
  ]);
  const [toast, setToast] = useState('');
  const [sidebar, setSidebar] = useState(true);
  const [modal, setModal] = useState<string|null>(null);
  const [selected, setSelected] = useState<Medicine|null>(null);
  const showToast = (text:string) => { setToast(text); window.setTimeout(() => setToast(''), 2600); };
  if (!loggedIn) return <Auth onLogin={(r:Role) => { setRole(r); setLoggedIn(true); }} />;
  const changePage = (p:string) => { setPage(p as Page); setModal(null); };
  return <div className="min-h-screen bg-slate-50 text-slate-900">
    <Sidebar open={sidebar} page={page} onNavigate={changePage} onLogout={() => setLoggedIn(false)} />
    <div className={`${sidebar ? 'lg:pl-[248px]' : 'lg:pl-[76px]'} transition-all duration-200`}>
      <Topbar onMenu={() => setSidebar(!sidebar)} page={page} onAlerts={() => changePage('alerts')} role={role} />
      <main className="p-4 sm:p-6 lg:p-8 max-w-[1600px] mx-auto animate-fade-in">
        {page === 'dashboard' && <Dashboard onNavigate={changePage} />}
        {page === 'inventory' && <Inventory inventory={inventory} setInventory={setInventory} onSelect={setSelected} onAdd={() => changePage('add-stock')} showToast={showToast} />}
        {page === 'add-stock' && <AddStock inventory={inventory} setInventory={setInventory} onDone={() => changePage('inventory')} showToast={showToast} />}
        {page === 'expiry' && <Expiry inventory={inventory} />}
        {page === 'dispensing' && <Dispensing inventory={inventory} setInventory={setInventory} audits={audits} setAudits={setAudits} showToast={showToast} />}
        {page === 'audit' && <Audit audits={audits} onSelect={(a) => { setModal('audit'); setSelected({id:0,medicine:a.medicine,batch:a.batch,expiry:'',quantity:a.quantity,supplier:'',status:'Available'}); }} />}
        {page === 'customers' && <Customers onSelect={(name) => { setModal('customer'); setSelected({id:0,medicine:name,batch:'',expiry:'',quantity:0,supplier:'',status:'Available'}); }} />}
        {page === 'alerts' && <Alerts onNavigate={changePage} />}
        {page === 'suppliers' && <Suppliers showToast={showToast} />}
        {page === 'recall' && <Recall showToast={showToast} />}
        {page === 'ai' && <Assistant inventory={inventory} />}
        {page === 'reports' && <Reports />}
        {page === 'settings' && <Settings showToast={showToast} />}
        {page === 'admin' && <Admin />}
        {page === 'users' && <UsersPage showToast={showToast} />}
        {page === 'system-audit' && <SystemAudit />}
      </main>
    </div>
    {toast && <div className="fixed bottom-6 right-6 z-50 flex items-center gap-3 rounded-xl bg-slate-900 text-white px-4 py-3 shadow-pop animate-slide-up text-sm"><CheckCircle2 size={18} className="text-emerald-400" />{toast}</div>}
    {modal === 'audit' && selected && <Drawer title="Dispensing record" onClose={() => setModal(null)}><div className="space-y-4"><Detail label="Medicine" value={selected.medicine} /><Detail label="Batch" value={selected.batch} /><Detail label="Quantity dispensed" value={`${selected.quantity} tablets`} /><Detail label="Status" value="Completed" /><button className="btn-primary w-full" onClick={() => setModal(null)}>Close record</button></div></Drawer>}
    {modal === 'customer' && selected && <Drawer title={selected.medicine} onClose={() => setModal(null)}><div className="flex items-center gap-3 pb-5 border-b border-slate-100"><div className="w-12 h-12 rounded-full bg-brand-100 text-brand-700 flex items-center justify-center font-bold text-lg">{selected.medicine.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><p className="font-semibold">{selected.medicine}</p><p className="text-xs text-slate-500">Customer profile</p></div></div><div className="mt-5 space-y-4"><Detail label="Phone" value="+91 ••••• 4812" /><Detail label="Total visits" value="12 dispensing visits" /><Detail label="Expiry notifications" value="Enabled" /><h4 className="font-semibold text-sm pt-3">Recent dispensing</h4><div className="rounded-lg bg-slate-50 p-3 text-sm">Vitamin D3 60K <span className="float-right text-slate-400">10 tablets</span></div></div></Drawer>}
  </div>;
}

function Auth({onLogin}:{onLogin:(r:Role)=>void}) {
  const [mode,setMode]=useState<'signin'|'signup'>('signin');
  const [role,setRole]=useState<Role>('Pharmacist');
  const [email,setEmail]=useState('pharmacist@demo.com');
  const [pass,setPass]=useState('password123');
  const [name,setName]=useState('');
  const [pharmacy,setPharmacy]=useState('');
  const [error,setError]=useState('');
  const submit=(e:React.FormEvent)=>{
    e.preventDefault();
    const adminOk = role==='Administrator' && email==='admin@demo.com' && pass==='password123';
    const pharmOk = role==='Pharmacist' && email==='pharmacist@demo.com' && pass==='password123';
    if (mode==='signup') { onLogin(role); return; }
    if (adminOk || pharmOk) onLogin(role);
    else setError(role==='Administrator' ? 'Use admin@demo.com / password123 for administrator access.' : 'Use pharmacist@demo.com / password123 for pharmacist access.');
  };
  return (
    <div className="min-h-screen bg-slate-50 flex flex-col lg:flex-row">
      {/* Left brand panel */}
      <div className="hidden lg:flex lg:w-[44%] bg-slate-900 relative overflow-hidden p-14 flex-col justify-between">
        <div className="absolute inset-0 opacity-[0.07]" style={{backgroundImage:'radial-gradient(#60a5fa 1px, transparent 1px)',backgroundSize:'22px 22px'}}></div>
        <div className="absolute -right-24 -top-24 w-96 h-96 rounded-full bg-brand-600/20 blur-3xl"></div>
        <div className="absolute -left-20 bottom-20 w-80 h-80 rounded-full bg-teal-600/10 blur-3xl"></div>
        <div className="relative flex items-center gap-3 text-white">
          <div className="w-11 h-11 rounded-xl bg-brand-600 flex items-center justify-center shadow-lg shadow-brand-600/30"><Stethoscope size={24}/></div>
          <span className="text-xl font-bold tracking-tight">PHARMA<span className="text-brand-400">FLOW</span></span>
        </div>
        <div className="relative max-w-lg">
          <div className="inline-flex items-center gap-2 rounded-full bg-white/10 border border-white/10 px-3 py-1.5 text-xs text-blue-200 mb-6">
            <ShieldCheck size={13}/> Pharmacy operations, simplified
          </div>
          <h1 className="text-[2.75rem] font-bold leading-[1.1] tracking-tight text-white">Pharmacy Medication Dispensing Audit &amp; Expiry Tracking Portal</h1>
          <p className="text-slate-400 mt-6 text-base leading-8">Make safer dispensing decisions with intelligent expiry tracking, audit-ready records, and real-time stock visibility across your pharmacy.</p>
          <div className="grid grid-cols-3 gap-6 mt-10 text-white">
            <div><p className="text-3xl font-bold">99.8%</p><p className="text-xs text-slate-400 mt-1">Audit accuracy</p></div>
            <div><p className="text-3xl font-bold">24/7</p><p className="text-xs text-slate-400 mt-1">Stock visibility</p></div>
            <div><p className="text-3xl font-bold">18.4K</p><p className="text-xs text-slate-400 mt-1">Units tracked</p></div>
          </div>
        </div>
        <p className="relative text-xs text-slate-500">© 2025 PharmaFlow Technologies · ISO 27001 certified</p>
      </div>

      {/* Right form panel */}
      <div className="flex-1 flex items-center justify-center p-6 sm:p-10">
        <div className="w-full max-w-[440px]">
          <div className="lg:hidden flex items-center gap-3 mb-10">
            <div className="w-10 h-10 rounded-xl bg-brand-600 text-white flex items-center justify-center"><Stethoscope size={22}/></div>
            <span className="text-xl font-bold">PHARMA<span className="text-brand-600">FLOW</span></span>
          </div>

          <div className="mb-7">
            <p className="text-xs font-bold text-brand-600 tracking-wider mb-2">{mode==='signin'?'WELCOME BACK':'GET STARTED'}</p>
            <h2 className="text-[1.75rem] font-bold tracking-tight leading-tight">{mode==='signin'?'Sign in to your workspace':'Create your account'}</h2>
            <p className="text-slate-500 mt-2 text-sm">{mode==='signin'?'Secure access to your pharmacy command center.':'Join your pharmacy team in a few quick steps.'}</p>
          </div>

          {/* Role selector */}
          <div className="mb-6">
            <label className="label">I am signing in as</label>
            <div className="grid grid-cols-2 gap-3">
              <button type="button" onClick={()=>{setRole('Pharmacist'); setEmail('pharmacist@demo.com'); setError('');}} className={`flex items-center gap-3 rounded-xl border p-3.5 text-left transition-all ${role==='Pharmacist'?'border-brand-500 bg-brand-50 ring-2 ring-brand-100':'border-slate-200 hover:border-slate-300'}`}>
                <div className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 ${role==='Pharmacist'?'bg-brand-600 text-white':'bg-slate-100 text-slate-500'}`}><Stethoscope size={18}/></div>
                <div><p className="text-sm font-semibold">Pharmacist</p><p className="text-[11px] text-slate-400">Dispensing &amp; stock</p></div>
              </button>
              <button type="button" onClick={()=>{setRole('Administrator'); setEmail('admin@demo.com'); setError('');}} className={`flex items-center gap-3 rounded-xl border p-3.5 text-left transition-all ${role==='Administrator'?'border-brand-500 bg-brand-50 ring-2 ring-brand-100':'border-slate-200 hover:border-slate-300'}`}>
                <div className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 ${role==='Administrator'?'bg-brand-600 text-white':'bg-slate-100 text-slate-500'}`}><ShieldCheck size={18}/></div>
                <div><p className="text-sm font-semibold">Administrator</p><p className="text-[11px] text-slate-400">Full workspace</p></div>
              </button>
            </div>
          </div>

          <form onSubmit={submit} className="space-y-4">
            {mode==='signup' && (
              <div className="grid grid-cols-2 gap-3">
                <div><label className="label">Full name</label><input className="input" placeholder="Dr. Anita Rao" value={name} onChange={e=>setName(e.target.value)}/></div>
                <div><label className="label">Pharmacy</label><input className="input" placeholder="WellCare" value={pharmacy} onChange={e=>setPharmacy(e.target.value)}/></div>
              </div>
            )}
            <div><label className="label">Work email</label><input className="input" value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="you@pharmacy.com"/></div>
            <div>
              <div className="flex justify-between"><label className="label">Password</label>{mode==='signin' && <button type="button" className="text-xs text-brand-600 font-medium mb-1.5">Forgot password?</button>}</div>
              <input className="input" value={pass} onChange={e=>setPass(e.target.value)} type="password" placeholder="••••••••"/>
            </div>
            {mode==='signup' && <div><label className="label">Confirm password</label><input className="input" type="password" placeholder="••••••••"/></div>}
            {error && <p className="text-sm text-red-600 bg-red-50 rounded-lg px-3 py-2 flex items-center gap-2"><AlertCircle size={15}/>{error}</p>}
            <label className="flex items-center gap-2 text-xs text-slate-500 select-none cursor-pointer">
              <input type="checkbox" className="rounded border-slate-300 text-brand-600 focus:ring-brand-200" defaultChecked/>
              I agree to the Terms of Service and Privacy Policy
            </label>
            <button className="btn-primary w-full py-2.5" type="submit">{mode==='signin'?'Sign in':'Create account'}<ChevronRight size={16}/></button>
          </form>

          <div className="relative flex items-center gap-3 my-6">
            <div className="h-px bg-slate-200 flex-1"/><span className="text-xs text-slate-400">DEMO ACCESS</span><div className="h-px bg-slate-200 flex-1"/>
          </div>
          <div className="rounded-xl bg-slate-50 border border-slate-200 p-4 text-sm">
            <p className="font-semibold text-slate-700 mb-2">Try the demo</p>
            <div className="space-y-1.5 text-xs text-slate-500">
              <p><b className="text-slate-700">Pharmacist:</b> pharmacist@demo.com · password123</p>
              <p><b className="text-slate-700">Administrator:</b> admin@demo.com · password123</p>
            </div>
          </div>
          <p className="text-sm text-center text-slate-500 mt-7">{mode==='signin'?'New to PharmaFlow?':'Already have an account?'} <button className="text-brand-600 font-semibold" onClick={()=>{setMode(mode==='signin'?'signup':'signin'); setError('');}}>{mode==='signin'?'Create an account':'Sign in'}</button></p>
        </div>
      </div>
    </div>
  );
}

function Sidebar({open,page,onNavigate,onLogout}:{open:boolean;page:Page;onNavigate:(p:string)=>void;onLogout:()=>void}) { return <aside className={`${open?'w-[248px]':'w-[76px]'} fixed inset-y-0 left-0 z-30 hidden lg:flex flex-col bg-white border-r border-slate-200 transition-all duration-200`}><div className="h-20 flex items-center px-5 gap-3 border-b border-slate-100"><div className="w-9 h-9 shrink-0 rounded-xl bg-brand-600 text-white flex items-center justify-center"><Stethoscope size={20}/></div>{open&&<span className="font-bold tracking-tight text-lg">PHARMA<span className="text-brand-600">FLOW</span></span>}</div><div className="flex-1 overflow-y-auto py-5 px-3"><p className={`text-[10px] uppercase tracking-widest font-bold text-slate-400 px-3 mb-3 ${!open&&'text-center'}`}>{open?'Workspace':'•••'}</p>{nav.map(({id,label,icon:Icon,count})=><button key={id} onClick={()=>onNavigate(id)} className={`w-full flex items-center gap-3 rounded-lg px-3 py-2.5 mb-1 text-sm font-medium transition-colors ${page===id?'bg-brand-50 text-brand-700':'text-slate-500 hover:bg-slate-50 hover:text-slate-900'} ${!open&&'justify-center'}`} title={!open?label:undefined}><Icon size={18} strokeWidth={page===id?2.5:1.8}/>{open&&<span className="flex-1 text-left">{label}</span>}{open&&count&&<span className="text-[10px] min-w-5 h-5 rounded-full bg-red-100 text-red-600 flex items-center justify-center font-bold">{count}</span>}</button>)}<p className={`text-[10px] uppercase tracking-widest font-bold text-slate-400 px-3 mb-3 mt-7 ${!open&&'text-center'}`}>{open?'Administration':'•••'}</p>{adminNav.map(({id,label,icon:Icon})=><button key={id} onClick={()=>onNavigate(id)} className={`w-full flex items-center gap-3 rounded-lg px-3 py-2.5 mb-1 text-sm font-medium transition-colors ${page===id?'bg-brand-50 text-brand-700':'text-slate-500 hover:bg-slate-50 hover:text-slate-900'} ${!open&&'justify-center'}`} title={!open?label:undefined}><Icon size={18}/>{open&&<span>{label}</span>}</button>)}</div><div className="p-3 border-t border-slate-100"><button onClick={onLogout} className={`w-full flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-slate-500 hover:bg-red-50 hover:text-red-600 ${!open&&'justify-center'}`}><LogOut size={18}/>{open&&'Sign out'}</button></div></aside> }

function Topbar({onMenu,page,onAlerts,role}:{onMenu:()=>void;page:Page;onAlerts:()=>void;role:Role}) { const title=page==='dashboard'?'Good morning, Dr. Anita':nav.concat(adminNav).find(x=>x.id===page)?.label||'PharmaFlow'; return <header className="h-20 bg-white border-b border-slate-200 flex items-center justify-between px-4 sm:px-6 lg:px-8 sticky top-0 z-20"><div className="flex items-center gap-3"><button onClick={onMenu} className="lg:hidden btn-ghost p-2"><Menu size={20}/></button><div><h1 className="text-lg font-bold tracking-tight">{title}</h1><p className="text-xs text-slate-400 hidden sm:block">{page==='dashboard'?'Here is what is happening across your pharmacy today.':'Manage your pharmacy operations'}</p></div></div><div className="flex items-center gap-2 sm:gap-4"><div className="hidden md:flex items-center gap-2 rounded-lg bg-slate-50 border border-slate-200 px-3 py-2 w-56"><Search size={16} className="text-slate-400"/><input className="bg-transparent outline-none text-sm w-full placeholder:text-slate-400" placeholder="Search anything..."/></div><button onClick={onAlerts} className="relative btn-ghost p-2"><Bell size={19}/><span className="absolute top-1.5 right-1.5 w-2 h-2 rounded-full bg-red-500 ring-2 ring-white"/></button><div className="w-px h-7 bg-slate-200 hidden sm:block"/><div className="flex items-center gap-2"><div className="w-8 h-8 rounded-full bg-brand-100 flex items-center justify-center text-brand-700 text-xs font-bold">AR</div><div className="hidden sm:block"><p className="text-xs font-semibold">Dr. Anita Rao</p><p className="text-[10px] text-slate-400">{role}</p></div><ChevronDown size={14} className="text-slate-400 hidden sm:block"/></div></div></header> }

function PageHeader({eyebrow,title,description,action}:{eyebrow?:string;title:string;description?:string;action?:React.ReactNode}) { return <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-7"><div>{eyebrow&&<p className="text-xs uppercase tracking-wider text-brand-600 font-bold mb-2">{eyebrow}</p>}<h2 className="text-2xl font-bold tracking-tight">{title}</h2>{description&&<p className="text-sm text-slate-500 mt-1.5">{description}</p>}</div>{action}</div> }
function Stat({label,value,change,icon:Icon,tone='blue'}:{label:string;value:string;change?:string;icon:React.ComponentType<{size?:number|string}>;tone?:string}) { const colors:Record<string,string>={blue:'bg-brand-50 text-brand-600',teal:'bg-teal-50 text-teal-700',green:'bg-emerald-50 text-emerald-600',amber:'bg-amber-50 text-amber-600',red:'bg-red-50 text-red-600'}; return <div className="card p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-500">{label}</p><p className="text-2xl font-bold mt-2 tracking-tight">{value}</p>{change&&<p className="text-xs mt-2 flex items-center gap-1 text-emerald-600"><ArrowUpRight size={13}/>{change}</p>}</div><div className={`w-10 h-10 rounded-lg flex items-center justify-center ${colors[tone]}`}><Icon size={20}/></div></div></div> }
function Panel({title,action,children,className=''}:{title:string;action?:React.ReactNode;children:React.ReactNode;className?:string}) { return <div className={`card ${className}`}><div className="px-5 py-4 border-b border-slate-100 flex items-center justify-between"><h3 className="font-semibold text-sm">{title}</h3>{action}</div>{children}</div> }
function Badge({status}:{status:Status|string}) { const map:Record<string,string>={Available:'bg-emerald-50 text-emerald-700', 'Near Expiry':'bg-amber-50 text-amber-700',Recalled:'bg-red-50 text-red-700','Low Stock':'bg-orange-50 text-orange-700',Expired:'bg-slate-100 text-slate-600',Completed:'bg-emerald-50 text-emerald-700'}; return <span className={`chip ${map[status]||'bg-slate-100 text-slate-600'}`}><span className="w-1.5 h-1.5 rounded-full bg-current"/>{status}</span> }
function Chart({type='line'}:{type?:string}) { return <div className="h-52 px-5 py-4"><div className="h-full relative"><div className="absolute inset-0 flex flex-col justify-between text-[10px] text-slate-400"><span>100</span><span>75</span><span>50</span><span>25</span><span>0</span></div><div className="absolute left-8 right-0 inset-y-0 flex flex-col justify-between">{[0,1,2,3,4].map(i=><div key={i} className="border-t border-slate-100"/>)}<svg className="absolute inset-0 w-full h-full overflow-visible" preserveAspectRatio="none" viewBox="0 0 600 180"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#2563EB" stopOpacity=".18"/><stop offset="1" stopColor="#2563EB" stopOpacity="0"/></linearGradient></defs>{type==='bar'?<>{[42,65,48,75,58,82,70,92,61,76,48,68].map((h,i)=><rect key={i} x={i*48+5} y={180-h*1.65} width="22" height={h*1.65} rx="4" fill={i%3===1?'#0F766E':'#93C5FD'}/>)}</>:<><path d="M0 135 C40 120 60 140 100 105 S160 130 200 84 S260 110 300 72 S370 92 400 48 S470 68 510 38 S560 64 600 18 L600 180 L0 180Z" fill="url(#fill)"/><path d="M0 135 C40 120 60 140 100 105 S160 130 200 84 S260 110 300 72 S370 92 400 48 S470 68 510 38 S560 64 600 18" fill="none" stroke="#2563EB" strokeWidth="3" strokeLinecap="round"/></>}</svg></div><div className="absolute left-8 right-0 bottom-[-18px] flex justify-between text-[10px] text-slate-400"><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span></div></div></div> }

function Dashboard({onNavigate}:{onNavigate:(p:string)=>void}) { return <><PageHeader eyebrow="Overview" title="Good morning, Dr. Anita" description="Here is what is happening across your pharmacy today." action={<button className="btn-primary" onClick={()=>onNavigate('dispensing')}><Plus size={16}/> New dispensing</button>}/><div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-4 mb-6"><Stat label="Medicines" value="128" change="4.2% vs last month" icon={Package} tone="blue"/><Stat label="Batches" value="246" change="2.1% vs last month" icon={Boxes} tone="teal"/><Stat label="Total stock" value="18,420" change="8.4% vs last month" icon={Activity} tone="green"/><Stat label="Low stock" value="7" icon={AlertTriangle} tone="amber"/><Stat label="Near expiry" value="12" icon={Clock3} tone="amber"/><Stat label="Expired" value="3" icon={AlertCircle} tone="red"/></div><div className="grid xl:grid-cols-3 gap-6 mb-6"><Panel title="Expiry risk overview" action={<button className="text-xs text-brand-600 font-semibold" onClick={()=>onNavigate('expiry')}>View report</button>} className="xl:col-span-2"><div className="px-5 pt-4 flex items-center gap-5"><div className="flex items-center gap-2 text-xs text-slate-500"><span className="w-2 h-2 rounded-full bg-brand-600"/>At risk batches</div><div className="flex items-center gap-2 text-xs text-slate-500"><span className="w-2 h-2 rounded-full bg-slate-300"/>Safe batches</div></div><Chart/></Panel><Panel title="Critical alerts" action={<button className="text-xs text-brand-600 font-semibold" onClick={()=>onNavigate('alerts')}>See all</button>}><div className="p-5 space-y-4"><AlertRow icon={AlertTriangle} tone="amber" title="Vitamin D3 60K expires soon" detail="Batch VD102 · 12 days left"/><AlertRow icon={AlertCircle} tone="red" title="Batch AMX204 recalled" detail="45 units · Action required"/><AlertRow icon={TrendingDownIcon} tone="orange" title="Paracetamol stock is low" detail="Only 12 units remaining"/></div></Panel></div><div className="grid xl:grid-cols-2 gap-6"><Panel title="Stock movement" action={<span className="text-xs text-slate-400">Last 6 months</span>}><Chart type="bar"/></Panel><Panel title="Most dispensed medicines" action={<button onClick={()=>onNavigate('reports')} className="text-xs text-brand-600 font-semibold">Full report</button>}><div className="p-5 space-y-4">{[['Paracetamol 500mg','2,480','32%'],['Cetirizine 10mg','1,842','24%'],['Metformin 500mg','1,490','19%'],['Vitamin D3 60K','988','13%']].map(([name,num,pct],i)=><div key={name}><div className="flex justify-between text-sm mb-2"><span className="font-medium">{name}</span><span className="text-slate-500">{num} <span className="text-xs text-slate-400">({pct})</span></span></div><div className="h-1.5 rounded-full bg-slate-100 overflow-hidden"><div className={`h-full rounded-full ${i===0?'bg-brand-600':i===1?'bg-teal-600':i===2?'bg-slate-500':'bg-amber-500'}`} style={{width:pct}}/></div></div>)}</div></Panel></div><div className="mt-6 rounded-xl bg-slate-900 text-white p-5 flex flex-col md:flex-row md:items-center gap-4"><div className="w-10 h-10 rounded-lg bg-brand-600 flex items-center justify-center shrink-0"><BrainCircuit size={21}/></div><div className="flex-1"><p className="text-xs text-blue-300 font-semibold uppercase tracking-wider">AI insight</p><p className="font-medium mt-1">Your Vitamin D3 inventory may exceed demand before expiry. Consider pausing the next order.</p></div><button onClick={()=>onNavigate('ai')} className="btn bg-white/10 text-white hover:bg-white/20 whitespace-nowrap">Ask AI assistant <ChevronRight size={15}/></button></div></> }
function TrendingDownIcon({size=18}:{size?:number|string}){return <ArrowDownRight size={size}/>} function AlertRow({icon:Icon,tone,title,detail}:{icon:React.ComponentType<{size?:number|string}>;tone:string;title:string;detail:string}){const c:Record<string,string>={amber:'bg-amber-50 text-amber-600',red:'bg-red-50 text-red-600',orange:'bg-orange-50 text-orange-600'};return <div className="flex gap-3"><div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${c[tone]}`}><Icon size={16}/></div><div><p className="text-sm font-medium">{title}</p><p className="text-xs text-slate-400 mt-0.5">{detail}</p></div></div>}

function Inventory({inventory,setInventory,onSelect,onAdd,showToast}:{inventory:Medicine[];setInventory:React.Dispatch<React.SetStateAction<Medicine[]>>;onSelect:(m:Medicine)=>void;onAdd:()=>void;showToast:(s:string)=>void}) { const [q,setQ]=useState(''); const [filter,setFilter]=useState('All'); const [edit,setEdit]=useState<Medicine|null>(null); const rows=inventory.filter(m=>(m.medicine+m.batch+m.supplier).toLowerCase().includes(q.toLowerCase())&&(filter==='All'||m.status===filter)); return <><PageHeader eyebrow="Stock control" title="Inventory" description="Track medicines, batches, and stock status in one place." action={<button onClick={onAdd} className="btn-primary"><Plus size={16}/> Add stock</button>}/><div className="card overflow-hidden"><div className="p-4 flex flex-col sm:flex-row gap-3 justify-between border-b border-slate-100"><div className="flex items-center gap-2 rounded-lg bg-slate-50 border border-slate-200 px-3 py-2 sm:w-80"><Search size={16} className="text-slate-400"/><input className="bg-transparent outline-none text-sm w-full" placeholder="Search medicine, batch..." value={q} onChange={e=>setQ(e.target.value)}/></div><div className="flex items-center gap-2"><SlidersHorizontal size={15} className="text-slate-400"/><select className="input sm:w-40 py-2" value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option><option>Available</option><option>Near Expiry</option><option>Low Stock</option><option>Recalled</option></select><button className="btn-secondary"><Download size={15}/> Export</button></div></div><div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-slate-50/70"><tr>{['Medicine','Batch','Expiry','Quantity','Supplier','Status',''].map(x=><th key={x} className="px-5 py-3 text-[11px] uppercase tracking-wider font-semibold text-slate-400">{x}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{rows.map(m=><tr key={m.id} className="hover:bg-slate-50/60"><td className="px-5 py-4"><button onClick={()=>onSelect(m)} className="font-semibold text-sm text-slate-800 hover:text-brand-600">{m.medicine}</button><p className="text-xs text-slate-400 mt-0.5">Updated today</p></td><td className="px-5 py-4 text-sm font-mono text-slate-600">{m.batch}</td><td className="px-5 py-4 text-sm text-slate-600">{m.expiry}</td><td className="px-5 py-4 text-sm font-semibold">{m.quantity}</td><td className="px-5 py-4 text-sm text-slate-600">{m.supplier}</td><td className="px-5 py-4"><Badge status={m.status}/></td><td className="px-5 py-4"><div className="flex justify-end gap-1"><button className="btn-ghost p-1.5" onClick={()=>setEdit(m)}><Edit3 size={15}/></button><button className="btn-ghost p-1.5 text-red-500" onClick={()=>{setInventory(inventory.filter(x=>x.id!==m.id));showToast('Medicine removed from inventory')}}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div><div className="px-5 py-3 border-t border-slate-100 text-xs text-slate-400">Showing {rows.length} of {inventory.length} medicines</div></div>{edit&&<Modal title="Edit medicine" onClose={()=>setEdit(null)}><div className="space-y-4"><div><label className="label">Medicine name</label><input className="input" value={edit.medicine} onChange={e=>setEdit({...edit,medicine:e.target.value})}/></div><div className="grid grid-cols-2 gap-3"><div><label className="label">Quantity</label><input className="input" type="number" value={edit.quantity} onChange={e=>setEdit({...edit,quantity:Number(e.target.value)})}/></div><div><label className="label">Status</label><select className="input" value={edit.status} onChange={e=>setEdit({...edit,status:e.target.value as Status})}><option>Available</option><option>Near Expiry</option><option>Low Stock</option><option>Recalled</option></select></div></div><button className="btn-primary w-full" onClick={()=>{setInventory(inventory.map(x=>x.id===edit.id?edit:x));setEdit(null);showToast('Inventory updated')}}>Save changes</button></div></Modal>}</> }

function AddStock({inventory,setInventory,onDone,showToast}:{inventory:Medicine[];setInventory:React.Dispatch<React.SetStateAction<Medicine[]>>;onDone:()=>void;showToast:(s:string)=>void}){const [tab,setTab]=useState('Barcode / QR');const [form,setForm]=useState({medicine:'',batch:'',expiry:'',quantity:'',supplier:''}); const demo=(kind:string)=>{setTab(kind);setForm(kind==='Invoice OCR'?{medicine:'Azithromycin 250mg',batch:'AZI118',expiry:'Dec 2027',quantity:'240',supplier:'MediSource'}:{medicine:'Metformin 500mg',batch:'MET624',expiry:'Feb 2028',quantity:'180',supplier:'ABC Pharma'});showToast(`${kind} captured medicine details`)};const submit=()=>{if(!form.medicine||!form.quantity){showToast('Please complete the medicine details');return}setInventory([...inventory,{id:Date.now(),medicine:form.medicine,batch:form.batch||'NEW001',expiry:form.expiry||'Dec 2027',quantity:Number(form.quantity),supplier:form.supplier||'ABC Pharma',status:'Available'}]);showToast('Stock added successfully');onDone()};return <><PageHeader eyebrow="Stock control" title="Add stock" description="Bring new stock into your inventory using the fastest method."/><div className="max-w-4xl"><div className="card"><div className="flex border-b border-slate-100">{['Barcode / QR','Invoice OCR','Manual entry'].map(t=><button key={t} onClick={()=>setTab(t)} className={`flex-1 py-4 text-sm font-semibold border-b-2 ${tab===t?'border-brand-600 text-brand-600':'border-transparent text-slate-400'}`}>{t}</button>)}</div>{tab!=='Manual entry'&&<div className="p-5 bg-brand-50/50 border-b border-brand-100 flex items-center justify-between"><div className="flex items-center gap-3"><div className="w-10 h-10 rounded-lg bg-white text-brand-600 flex items-center justify-center shadow-sm">{tab==='Invoice OCR'?<FileText size={20}/>:<QrCode size={20}/>}</div><div><p className="font-semibold text-sm">{tab==='Invoice OCR'?'Extract details from invoice':'Scan a medicine barcode'}</p><p className="text-xs text-slate-500 mt-0.5">Use our demo capture to auto-fill realistic details.</p></div></div><button className="btn-primary" onClick={()=>demo(tab)}>Demo {tab==='Invoice OCR'?'OCR':'Scan'}</button></div>}<div className="p-6 grid sm:grid-cols-2 gap-5"><div className="sm:col-span-2"><label className="label">Medicine name</label><input className="input" placeholder="e.g. Paracetamol 500mg" value={form.medicine} onChange={e=>setForm({...form,medicine:e.target.value})}/></div><div><label className="label">Batch number</label><input className="input" placeholder="e.g. PCT101" value={form.batch} onChange={e=>setForm({...form,batch:e.target.value})}/></div><div><label className="label">Expiry date</label><input className="input" placeholder="e.g. Sep 2027" value={form.expiry} onChange={e=>setForm({...form,expiry:e.target.value})}/></div><div><label className="label">Quantity</label><input className="input" type="number" placeholder="0" value={form.quantity} onChange={e=>setForm({...form,quantity:e.target.value})}/></div><div><label className="label">Supplier</label><select className="input" value={form.supplier} onChange={e=>setForm({...form,supplier:e.target.value})}><option value="">Select supplier</option><option>ABC Pharma</option><option>MediSource</option><option>HealthCare Labs</option><option>Nova Pharma</option></select></div><div className="sm:col-span-2 pt-2 flex justify-end gap-3"><button className="btn-secondary" onClick={onDone}>Cancel</button><button className="btn-primary" onClick={submit}><PackagePlus size={16}/> Add to inventory</button></div></div></div></div></>}

function Expiry({inventory}:{inventory:Medicine[]}){return <><PageHeader eyebrow="Risk management" title="Batch & expiry" description="Stay ahead of expiry risk with a clear view of every batch." action={<button className="btn-secondary"><Download size={15}/> Export report</button>}/><div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6"><Stat label="Total batches" value="246" icon={Boxes} tone="blue"/><Stat label="Expiring in 30 days" value="12" icon={Clock3} tone="amber"/><Stat label="Expiring in 90 days" value="28" icon={CalendarDays} tone="teal"/><Stat label="Expired batches" value="3" icon={AlertCircle} tone="red"/></div><div className="grid xl:grid-cols-3 gap-6"><Panel title="Expiry timeline" className="xl:col-span-2"><div className="p-6"><div className="flex items-center justify-between mb-8 text-xs text-slate-400"><span>Today</span><span>30 days</span><span>60 days</span><span>90 days</span><span>120 days</span></div><div className="relative h-28 border-t border-slate-200"><div className="absolute inset-x-0 top-0 flex justify-between"><span className="w-px h-32 bg-slate-200"/><span className="w-px h-32 bg-slate-200"/><span className="w-px h-32 bg-slate-200"/><span className="w-px h-32 bg-slate-200"/><span className="w-px h-32 bg-slate-200"/></div><div className="absolute top-5 left-[12%] bg-red-50 border border-red-200 text-red-700 rounded-lg px-3 py-2 text-xs font-semibold shadow-sm"><span className="block">AMX204</span><span className="font-normal">Oct 2026 · Recalled</span></div><div className="absolute top-20 left-[24%] bg-amber-50 border border-amber-200 text-amber-700 rounded-lg px-3 py-2 text-xs font-semibold shadow-sm"><span className="block">VD102</span><span className="font-normal">Sep 2026 · High risk</span></div></div></div></Panel><Panel title="Risk distribution"><div className="p-6 flex items-center justify-center"><div className="relative w-40 h-40 rounded-full" style={{background:'conic-gradient(#DC2626 0 4%, #F59E0B 4% 16%, #14B8A6 16% 30%, #E2E8F0 30% 100%)'}}><div className="absolute inset-5 bg-white rounded-full flex flex-col items-center justify-center"><p className="text-3xl font-bold">246</p><p className="text-xs text-slate-400">batches</p></div></div></div><div className="space-y-3 px-6 pb-5">{[['Expired','3','#DC2626'],['High risk','12','#F59E0B'],['Watch','34','#14B8A6'],['Safe','197','#CBD5E1']].map(([n,v,c])=><div className="flex items-center justify-between text-sm" key={n}><span className="flex gap-2 items-center"><span className="w-2 h-2 rounded-full" style={{background:c}}/>{n}</span><b>{v}</b></div>)}</div></Panel></div><Panel title="Priority batches" action={<button className="btn-ghost p-1.5"><MoreHorizontal size={17}/></button>} className="mt-6"><div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-slate-50"><tr>{['Medicine','Batch','Expiry','Days left','Risk','Action'].map(x=><th key={x} className="px-5 py-3 text-[11px] uppercase tracking-wider text-slate-400">{x}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{inventory.slice(1,5).map((m,i)=><tr key={m.batch}><td className="px-5 py-4 text-sm font-semibold">{m.medicine}</td><td className="px-5 py-4 text-sm font-mono">{m.batch}</td><td className="px-5 py-4 text-sm text-slate-500">{m.expiry}</td><td className="px-5 py-4 text-sm font-semibold">{i===0?'12':i===1?'42':i===2?'68':'103'}</td><td className="px-5 py-4"><Badge status={i<2?'Near Expiry':'Available'}/></td><td className="px-5 py-4"><button className="text-xs text-brand-600 font-semibold">Review batch</button></td></tr>)}</tbody></table></div></Panel></>}

function Dispensing({inventory,setInventory,audits,setAudits,showToast}:{inventory:Medicine[];setInventory:React.Dispatch<React.SetStateAction<Medicine[]>>;audits:Audit[];setAudits:React.Dispatch<React.SetStateAction<Audit[]>>;showToast:(s:string)=>void}){const [medicine,setMedicine]=useState('');const [batch,setBatch]=useState('');const [qty,setQty]=useState(1);const [customer,setCustomer]=useState('');const chosen=inventory.find(x=>x.medicine===medicine&&(!batch||x.batch===batch)); const confirm=()=>{if(!chosen||!customer||qty<1){showToast('Complete all dispensing details');return}if(qty>chosen.quantity){showToast(`Only ${chosen.quantity} units available in this batch`);return}setInventory(inventory.map(x=>x.id===chosen.id?{...x,quantity:x.quantity-qty}:x));setAudits([{id:Date.now(),date:'Just now',medicine:chosen.medicine,batch:chosen.batch,quantity:qty,customer,pharmacist:'Dr. Anita Rao',status:'Completed'},...audits]);showToast('Dispensing confirmed and audit logged');setMedicine('');setBatch('');setQty(1);setCustomer('')};return <><PageHeader eyebrow="Daily operations" title="Dispensing" description="Safely dispense medication with full batch traceability."/><div className="grid xl:grid-cols-3 gap-6"><div className="card xl:col-span-2"><div className="p-5 border-b border-slate-100 flex items-center gap-3"><div className="w-9 h-9 rounded-lg bg-brand-50 text-brand-600 flex items-center justify-center"><CreditCard size={18}/></div><div><h3 className="font-semibold">New dispensing record</h3><p className="text-xs text-slate-400 mt-0.5">Record what leaves your pharmacy.</p></div></div><div className="p-6 grid sm:grid-cols-2 gap-5"><div className="sm:col-span-2"><label className="label">Select medicine</label><select className="input" value={medicine} onChange={e=>{setMedicine(e.target.value);setBatch('')}}><option value="">Choose medicine</option>{inventory.filter(x=>x.status!=='Recalled').map(x=><option key={x.id}>{x.medicine}</option>)}</select></div><div><label className="label">Select batch</label><select className="input" value={batch} onChange={e=>setBatch(e.target.value)} disabled={!medicine}><option value="">{chosen?'Auto-select FEFO batch':'Choose batch'}</option>{inventory.filter(x=>x.medicine===medicine).map(x=><option key={x.batch} value={x.batch}>{x.batch} · {x.quantity} units · {x.expiry}</option>)}</select></div><div><label className="label">Quantity</label><input className="input" type="number" min="1" value={qty} onChange={e=>setQty(Number(e.target.value))}/>{chosen&&<p className="text-xs text-slate-400 mt-1">Available: {chosen.quantity} units</p>}</div><div><label className="label">Customer</label><select className="input" value={customer} onChange={e=>setCustomer(e.target.value)}><option value="">Select customer</option>{customers.map(x=><option key={x}>{x}</option>)}</select></div><div><label className="label">Preferred language</label><select className="input"><option>English</option><option>Hindi</option><option>Malayalam</option><option>Tamil</option></select></div><div className="sm:col-span-2 pt-3 flex justify-end"><button className="btn-primary px-6" onClick={confirm}><Check size={16}/> Confirm dispensing</button></div></div></div><div className="space-y-6"><Panel title="Dispensing today"><div className="p-5"><p className="text-4xl font-bold">42</p><p className="text-xs text-slate-400 mt-1">records completed today</p><div className="h-2 bg-slate-100 rounded-full mt-5 overflow-hidden"><div className="h-full bg-brand-600 w-[72%] rounded-full"/></div><div className="flex justify-between text-xs mt-2"><span className="text-slate-500">Daily target</span><b>72%</b></div></div></Panel><Panel title="Recent records"><div className="divide-y divide-slate-100">{audits.slice(0,3).map(a=><div className="p-4" key={a.id}><div className="flex justify-between"><p className="text-sm font-medium truncate pr-2">{a.medicine}</p><span className="text-xs text-slate-400">{a.quantity}x</span></div><p className="text-xs text-slate-400 mt-1">{a.customer} · {a.date}</p></div>)}</div></Panel></div></div></>}

function Audit({audits,onSelect}:{audits:Audit[];onSelect:(a:Audit)=>void}){const [q,setQ]=useState('');const rows=audits.filter(a=>(a.medicine+a.customer+a.batch).toLowerCase().includes(q.toLowerCase()));return <><PageHeader eyebrow="Compliance" title="Dispensing audit" description="Every dispensing event, traceable and review-ready." action={<button className="btn-secondary"><Download size={15}/> Export audit</button>}/><div className="card overflow-hidden"><div className="p-4 border-b border-slate-100"><div className="flex items-center gap-2 rounded-lg bg-slate-50 border border-slate-200 px-3 py-2 sm:w-80"><Search size={16} className="text-slate-400"/><input className="bg-transparent outline-none text-sm w-full" placeholder="Search audit records..." value={q} onChange={e=>setQ(e.target.value)}/></div></div><div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-slate-50"><tr>{['Date','Medicine','Batch','Quantity','Customer','Pharmacist','Status',''].map(x=><th key={x} className="px-5 py-3 text-[11px] uppercase tracking-wider text-slate-400">{x}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{rows.map(a=><tr key={a.id} className="hover:bg-slate-50"><td className="px-5 py-4 text-xs text-slate-500">{a.date}</td><td className="px-5 py-4 text-sm font-semibold">{a.medicine}</td><td className="px-5 py-4 font-mono text-sm">{a.batch}</td><td className="px-5 py-4 text-sm">{a.quantity}</td><td className="px-5 py-4 text-sm text-slate-600">{a.customer}</td><td className="px-5 py-4 text-sm text-slate-600">{a.pharmacist}</td><td className="px-5 py-4"><Badge status={a.status}/></td><td className="px-5 py-4"><button className="text-xs text-brand-600 font-semibold" onClick={()=>onSelect(a)}>View</button></td></tr>)}</tbody></table></div></div></>}

function Customers({onSelect}:{onSelect:(n:string)=>void}){const data=customers.map((name,i)=>({name,visits:[12,8,6,4,3][i],last:['Today','Yesterday','Aug 18','Aug 12','Aug 04'][i],phone:['4812','9034','7710','2258','6419'][i]}));return <><PageHeader eyebrow="Relationships" title="Customers" description="Keep customer care personal, informed, and connected." action={<button className="btn-primary"><Plus size={16}/> Add customer</button>}/><div className="card overflow-hidden"><div className="p-4 border-b border-slate-100 flex items-center justify-between"><div className="flex items-center gap-2 rounded-lg bg-slate-50 border border-slate-200 px-3 py-2 sm:w-80"><Search size={16} className="text-slate-400"/><input className="bg-transparent outline-none text-sm w-full" placeholder="Search customers..."/></div><button className="btn-secondary hidden sm:flex"><Download size={15}/> Export</button></div><div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4 p-5">{data.map((c,i)=><button key={c.name} onClick={()=>onSelect(c.name)} className="text-left border border-slate-200 rounded-xl p-4 hover:border-brand-300 hover:shadow-card transition-all"><div className="flex items-center gap-3"><div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm ${i%2?'bg-teal-50 text-teal-700':'bg-brand-50 text-brand-700'}`}>{c.name.split(' ').map(x=>x[0]).join('')}</div><div><p className="font-semibold text-sm">{c.name}</p><p className="text-xs text-slate-400">+91 ••••• {c.phone}</p></div></div><div className="flex gap-5 mt-5 pt-4 border-t border-slate-100"><div><p className="text-lg font-bold">{c.visits}</p><p className="text-[11px] text-slate-400">Visits</p></div><div><p className="text-sm font-semibold mt-1">{c.last}</p><p className="text-[11px] text-slate-400 mt-1">Last dispensing</p></div><div className="ml-auto flex items-end"><span className="chip bg-emerald-50 text-emerald-700">Alerts on</span></div></div></button>)}</div></div></>}

function Alerts({onNavigate}:{onNavigate:(p:string)=>void}){const cards=[{title:'Vitamin D3 60K expires soon',detail:'Batch VD102 expires in 12 days. 180 units at risk.',type:'Near expiry',tone:'amber',action:'Review batch',page:'expiry'},{title:'Paracetamol stock is low',detail:'PCT101 has dropped below your minimum threshold.',type:'Low stock',tone:'orange',action:'Add stock',page:'add-stock'},{title:'AMX204 recalled by supplier',detail:'45 units remaining. 18 customers may be affected.',type:'Recall',tone:'red',action:'View recall',page:'recall'},{title:'Weekly expiry digest ready',detail:'Your scheduled pharmacy summary is ready to view.',type:'Report',tone:'blue',action:'View report',page:'reports'}];return <><PageHeader eyebrow="Stay informed" title="Alerts" description="Important actions, surfaced before they become problems." action={<button className="btn-secondary"><Check size={15}/> Mark all read</button>}/><div className="grid lg:grid-cols-2 gap-4">{cards.map(a=><div key={a.title} className="card p-5 flex gap-4 hover:shadow-pop transition-shadow"><div className={`w-11 h-11 rounded-xl shrink-0 flex items-center justify-center ${a.tone==='red'?'bg-red-50 text-red-600':a.tone==='amber'?'bg-amber-50 text-amber-600':a.tone==='orange'?'bg-orange-50 text-orange-600':'bg-brand-50 text-brand-600'}`}>{a.tone==='red'?<AlertCircle size={21}/>:a.tone==='amber'?<Clock3 size={21}/>:a.tone==='orange'?<Package size={21}/>:<FileText size={21}/>}</div><div className="flex-1"><div className="flex justify-between gap-3"><p className="font-semibold text-sm">{a.title}</p><span className={`chip shrink-0 ${a.tone==='red'?'bg-red-50 text-red-700':a.tone==='amber'?'bg-amber-50 text-amber-700':a.tone==='orange'?'bg-orange-50 text-orange-700':'bg-brand-50 text-brand-700'}`}>{a.type}</span></div><p className="text-sm text-slate-500 mt-2 leading-6">{a.detail}</p><button onClick={()=>onNavigate(a.page)} className="text-xs text-brand-600 font-semibold mt-3">{a.action} <ChevronRight size={13} className="inline"/></button></div></div>)}</div></>}

function Suppliers({showToast}:{showToast:(s:string)=>void}){const suppliers=[['ABC Pharma','24 batches','₹ 2,48,600','Excellent'],['MediSource','18 batches','₹ 1,82,400','Good'],['HealthCare Labs','12 batches','₹ 98,200','Good'],['Nova Pharma','9 batches','₹ 74,800','Excellent']];const [modal,setModal]=useState(false);return <><PageHeader eyebrow="Procurement" title="Suppliers & returns" description="Manage supplier relationships and return stock with confidence." action={<button className="btn-primary" onClick={()=>setModal(true)}><RotateCcw size={16}/> Create return</button>}/><div className="grid sm:grid-cols-3 gap-4 mb-6"><Stat label="Active suppliers" value="18" icon={Truck} tone="blue"/><Stat label="Pending returns" value="4" icon={RotateCcw} tone="amber"/><Stat label="This month spend" value="₹ 6.8L" icon={CreditCard} tone="teal"/></div><Panel title="Supplier directory"><div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-slate-50"><tr>{['Supplier','Active batches','Total purchases','Rating',''].map(x=><th key={x} className="px-5 py-3 text-[11px] uppercase tracking-wider text-slate-400">{x}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{suppliers.map(s=><tr key={s[0]}><td className="px-5 py-4"><p className="font-semibold text-sm">{s[0]}</p><p className="text-xs text-slate-400">supp••••@{s[0].split(' ')[0].toLowerCase()}.com</p></td><td className="px-5 py-4 text-sm">{s[1]}</td><td className="px-5 py-4 text-sm font-semibold">{s[2]}</td><td className="px-5 py-4"><span className="chip bg-emerald-50 text-emerald-700"><span className="text-amber-500">★</span>{s[3]}</span></td><td className="px-5 py-4 text-right"><button className="btn-ghost p-1.5"><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table></div></Panel>{modal&&<Modal title="Create stock return" onClose={()=>setModal(false)}><div className="space-y-4"><div><label className="label">Supplier</label><select className="input"><option>MediSource</option><option>ABC Pharma</option><option>HealthCare Labs</option></select></div><div><label className="label">Batch to return</label><select className="input"><option>AMX204 · Amoxicillin 500mg · 45 units</option><option>VD102 · Vitamin D3 60K · 20 units</option></select></div><div><label className="label">Reason</label><select className="input"><option>Product recall</option><option>Near expiry</option><option>Damaged stock</option></select></div><div><label className="label">Notes</label><textarea className="input h-20" placeholder="Add return notes..."/></div><button className="btn-primary w-full" onClick={()=>{setModal(false);showToast('Return request created successfully')}}>Create return request</button></div></Modal>}</>}

function Recall({showToast}:{showToast:(s:string)=>void}){return <><PageHeader eyebrow="Safety controls" title="Batch recall" description="Contain recalled medicines and protect affected customers." action={<button className="btn-danger" onClick={()=>showToast('Recall notice sent to 18 affected customers')}><Send size={15}/> Send notification</button>}/><div className="card border-red-200 overflow-hidden"><div className="p-5 bg-red-50/70 border-b border-red-100 flex items-start gap-4"><div className="w-11 h-11 rounded-xl bg-red-100 text-red-600 flex items-center justify-center"><AlertCircle size={22}/></div><div><div className="flex items-center gap-2"><h3 className="font-bold">Amoxicillin 500mg · AMX204</h3><Badge status="Recalled"/></div><p className="text-sm text-red-700 mt-1">Supplier recall issued on 18 Aug 2025 due to quality concerns.</p></div></div><div className="p-6 grid sm:grid-cols-3 gap-6"><div><p className="text-xs text-slate-400">Units remaining</p><p className="text-3xl font-bold mt-1">45</p><p className="text-xs text-red-600 mt-1">Must be blocked</p></div><div><p className="text-xs text-slate-400">Customers affected</p><p className="text-3xl font-bold mt-1">18</p><p className="text-xs text-amber-600 mt-1">Notifications pending</p></div><div><p className="text-xs text-slate-400">Dispensed this month</p><p className="text-3xl font-bold mt-1">27</p><p className="text-xs text-slate-500 mt-1">Across 6 transactions</p></div></div><div className="p-6 border-t border-slate-100 flex flex-wrap gap-3"><button className="btn-secondary" onClick={()=>showToast('Showing customer impact report')}><Users size={15}/> View impact</button><button className="btn-danger" onClick={()=>showToast('Batch AMX204 has been blocked')}><ShieldCheck size={15}/> Block batch</button><button className="btn-secondary" onClick={()=>showToast('Notification queued for affected customers')}><Send size={15}/> Send notification</button></div></div><div className="mt-6"><Panel title="Recall activity"><div className="p-5 space-y-5"><Timeline title="Recall created" detail="Dr. Anita Rao created this recall case" time="Today, 09:12 AM"/><Timeline title="Supplier notice received" detail="MediSource marked batch AMX204 for recall" time="Yesterday, 04:20 PM"/><Timeline title="Initial stock check" detail="45 units located in main storage" time="Yesterday, 04:28 PM"/></div></Panel></div></>}
function Timeline({title,detail,time}:{title:string;detail:string;time:string}){return <div className="flex gap-4"><div className="relative"><div className="w-8 h-8 rounded-full bg-brand-50 text-brand-600 flex items-center justify-center"><Check size={15}/></div><div className="absolute top-8 bottom-[-20px] left-4 w-px bg-slate-200 last:hidden"/></div><div className="flex-1"><div className="flex justify-between"><p className="text-sm font-semibold">{title}</p><span className="text-xs text-slate-400">{time}</span></div><p className="text-xs text-slate-500 mt-1">{detail}</p></div></div>}

function Assistant({inventory}:{inventory:Medicine[]}){const [messages,setMessages]=useState<{from:'ai'|'user';text:string}[]>([{from:'ai',text:'Hello, Dr. Anita. I can help you understand stock levels, expiry risks, dispensing patterns, and more. What would you like to know?'}]);const [input,setInput]=useState('');const answer=(q:string)=>{const l=q.toLowerCase();if(l.includes('expire'))return 'I found 12 batches expiring within 30 days. The highest priority is Vitamin D3 60K (VD102), with 180 units and 12 days remaining. I recommend pausing replenishment and prioritising this batch for dispensing.';if(l.includes('low'))return 'There are 7 medicines below your low-stock threshold. Paracetamol 500mg is the most urgent at 12 units, followed by Azithromycin 250mg at 68 units.';if(l.includes('return'))return 'Two batches should be considered for return: AMX204 is recalled with 45 units remaining, and VD102 has 180 units at high expiry risk.';return 'Based on your recent activity, dispensing is steady and stock coverage is healthy. I noticed Vitamin D3 may be overstocked relative to its expiry window — would you like me to model a smaller reorder?'};const send=(text=input)=>{if(!text.trim())return;setMessages([...messages,{from:'user',text},{from:'ai',text:answer(text)}]);setInput('')};return <><PageHeader eyebrow="Intelligence" title="AI pharmacy assistant" description="Ask questions about your pharmacy operations in plain language."/><div className="grid xl:grid-cols-3 gap-6"><div className="card xl:col-span-2 flex flex-col min-h-[560px]"><div className="p-5 border-b border-slate-100 flex items-center gap-3"><div className="w-9 h-9 rounded-lg bg-slate-900 text-white flex items-center justify-center"><BrainCircuit size={18}/></div><div><p className="font-semibold text-sm">PharmaFlow intelligence</p><p className="text-xs text-emerald-600 flex items-center gap-1 mt-0.5"><span className="w-1.5 h-1.5 rounded-full bg-emerald-500"/>Online · Uses your pharmacy data</p></div></div><div className="flex-1 p-5 space-y-5 overflow-y-auto">{messages.map((m,i)=><div key={i} className={`flex gap-3 ${m.from==='user'?'justify-end':''}`}><div className={`max-w-[80%] rounded-xl px-4 py-3 text-sm leading-6 ${m.from==='user'?'bg-brand-600 text-white':'bg-slate-100 text-slate-700'}`}>{m.text}</div></div>)}</div><div className="px-5 pb-5"><div className="flex flex-wrap gap-2 mb-3">{['Which medicines expire within 30 days?','Which medicines are low in stock?','Which batches need return?','Show unusual dispensing activity?'].map(q=><button key={q} onClick={()=>send(q)} className="text-xs rounded-full border border-slate-200 px-3 py-1.5 text-slate-600 hover:border-brand-300 hover:text-brand-600">{q}</button>)}</div><div className="flex gap-2"><input className="input" placeholder="Ask about your pharmacy..." value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()}/><button className="btn-primary px-3" onClick={()=>send()}><Send size={16}/></button></div></div></div><WhatIf inventory={inventory}/></div></>}
function WhatIf({inventory}:{inventory:Medicine[]}){const [medicine,setMedicine]=useState('Vitamin D3 60K');const [current,setCurrent]=useState(180);const [order,setOrder]=useState(300);const [daily,setDaily]=useState(5);const [days,setDays]=useState(45);const total=current+order;const usage=daily*days;const unused=Math.max(total-usage,0);const risk=unused>total*.5?'HIGH RISK':unused>total*.25?'MEDIUM RISK':'LOW RISK';return <Panel title="What-if simulator"><div className="p-5 space-y-4"><div><label className="label">Medicine</label><select className="input" value={medicine} onChange={e=>setMedicine(e.target.value)}>{inventory.map(m=><option key={m.id}>{m.medicine}</option>)}</select></div>{[['Current stock',current,setCurrent],['New order',order,setOrder],['Daily usage',daily,setDaily],['Days to expiry',days,setDays]].map(([label,val,setter])=><div key={label as string}><label className="label">{label as string}</label><input className="input" type="number" value={val as number} onChange={e=>(setter as React.Dispatch<React.SetStateAction<number>>)(Number(e.target.value))}/></div>)}<div className={`rounded-xl p-4 ${risk==='HIGH RISK'?'bg-red-50 text-red-800':risk==='MEDIUM RISK'?'bg-amber-50 text-amber-800':'bg-emerald-50 text-emerald-800'}`}><div className="flex items-center justify-between"><span className="font-bold text-sm">{risk}</span><AlertTriangle size={18}/></div><div className="grid grid-cols-3 gap-2 mt-4 text-xs"><div><p className="opacity-70">Total stock</p><b className="text-base">{total}</b></div><div><p className="opacity-70">Expected usage</p><b className="text-base">{usage}</b></div><div><p className="opacity-70">Unused stock</p><b className="text-base">{unused}</b></div></div></div>{risk==='HIGH RISK'&&<p className="text-xs text-slate-500 leading-5">Consider a smaller order or verify expected demand. This order may leave stock unused before expiry.</p>}</div></Panel>}

function Reports(){return <><PageHeader eyebrow="Insights" title="Reports" description="Turn pharmacy activity into decisions." action={<button className="btn-primary"><Download size={15}/> Export report</button>}/><div className="flex flex-wrap gap-2 mb-5"><button className="btn-secondary">Last 30 days <ChevronDown size={14}/></button><button className="btn-secondary"><Filter size={14}/> All locations</button></div><div className="grid xl:grid-cols-2 gap-6"><Panel title="Dispensing trend" action={<span className="text-xs text-emerald-600">+12.4% vs prior period</span>}><Chart/></Panel><Panel title="Stock movement"><Chart type="bar"/></Panel><Panel title="Expiry risk by month"><div className="p-5 space-y-4">{[['Sep 2025','12','bg-red-500'],['Oct 2025','18','bg-amber-500'],['Nov 2025','28','bg-amber-400'],['Dec 2025','34','bg-teal-500'],['Jan 2026','42','bg-slate-300']].map(x=><div className="flex items-center gap-3" key={x[0]}><span className="w-16 text-xs text-slate-500">{x[0]}</span><div className="flex-1 h-5 bg-slate-100 rounded overflow-hidden"><div className={`h-full ${x[2]} rounded`} style={{width:`${Number(x[1])*1.8}%`}}/></div><span className="w-6 text-right text-xs font-semibold">{x[1]}</span></div>)}</div></Panel><Panel title="Top medicines"><div className="p-5 space-y-3">{['Paracetamol 500mg','Cetirizine 10mg','Metformin 500mg','Vitamin D3 60K','Azithromycin 250mg'].map((x,i)=><div className="flex items-center gap-3 text-sm" key={x}><span className="w-6 text-xs text-slate-400">0{i+1}</span><span className="flex-1 font-medium">{x}</span><span className="font-semibold">{['2,480','1,842','1,490','988','642'][i]}</span><ArrowUpRight size={14} className="text-emerald-500"/></div>)}</div></Panel></div></>}

function Settings({showToast}:{showToast:(s:string)=>void}){const [section,setSection]=useState('Profile');const sections=['Profile','Pharmacy','Alerts','Languages','AI preferences','Security'];return <><PageHeader eyebrow="Workspace" title="Settings" description="Configure PharmaFlow around the way your pharmacy works."/><div className="grid lg:grid-cols-[220px_1fr] gap-6"><div className="card p-2 h-fit">{sections.map(x=><button key={x} onClick={()=>setSection(x)} className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium ${section===x?'bg-brand-50 text-brand-700':'text-slate-500 hover:bg-slate-50'}`}>{x}</button>)}</div><div className="card"><div className="px-6 py-5 border-b border-slate-100"><h3 className="font-semibold">{section} settings</h3><p className="text-xs text-slate-400 mt-1">Manage your {section.toLowerCase()} preferences.</p></div><div className="p-6 space-y-5 max-w-xl">{section==='Profile'?<><div className="flex items-center gap-4"><div className="w-16 h-16 rounded-full bg-brand-100 text-brand-700 flex items-center justify-center text-xl font-bold">AR</div><button className="btn-secondary">Change photo</button></div><div className="grid sm:grid-cols-2 gap-4"><div><label className="label">First name</label><input className="input" defaultValue="Anita"/></div><div><label className="label">Last name</label><input className="input" defaultValue="Rao"/></div></div><div><label className="label">Work email</label><input className="input" defaultValue="pharmacist@demo.com"/></div></>:['Alerts','AI preferences','Security'].includes(section)?<>{['Low stock alerts','Expiry notifications','Recall notifications','Weekly summary'].map((x,i)=><div className="flex items-center justify-between py-2" key={x}><div><p className="text-sm font-medium">{x}</p><p className="text-xs text-slate-400 mt-1">Receive updates about {x.toLowerCase()}.</p></div><button className={`w-10 h-6 rounded-full p-1 ${i===3?'bg-slate-200':'bg-brand-600'}`}><span className={`block w-4 h-4 bg-white rounded-full transition-transform ${i===3?'':'translate-x-4'}`}/></button></div>)}</>:<><div><label className="label">Pharmacy name</label><input className="input" defaultValue="WellCare Pharmacy"/></div><div><label className="label">Timezone</label><select className="input"><option>Asia/Kolkata (GMT+5:30)</option><option>UTC</option></select></div></>}<button className="btn-primary" onClick={()=>showToast('Settings saved successfully')}>Save changes</button></div></div></div></>}

function Admin(){return <><PageHeader eyebrow="Administration" title="Admin dashboard" description="A high-level view of your pharmacy workspace."/><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-6"><Stat label="Team members" value="18" change="2 new this month" icon={Users} tone="blue"/><Stat label="Pharmacists" value="14" icon={Stethoscope} tone="teal"/><Stat label="Admins" value="4" icon={ShieldCheck} tone="amber"/><Stat label="System uptime" value="99.9%" icon={Activity} tone="green"/></div><div className="grid xl:grid-cols-2 gap-6"><Panel title="Team activity"><div className="p-5 space-y-4"><Timeline title="New pharmacist invited" detail="Dr. Neha Menon was added to the team" time="Today, 08:45 AM"/><Timeline title="Settings updated" detail="Alert preferences were changed by Admin" time="Yesterday, 03:20 PM"/><Timeline title="Audit export generated" detail="Monthly compliance report downloaded" time="Aug 18, 11:04 AM"/></div></Panel><Panel title="Workspace health"><div className="p-5 space-y-5"><div className="flex justify-between items-end"><div><p className="text-xs text-slate-400">Data completeness</p><p className="text-2xl font-bold mt-1">94%</p></div><span className="text-xs text-emerald-600 font-semibold">Healthy</span></div><div className="h-2 rounded-full bg-slate-100"><div className="h-full w-[94%] bg-emerald-500 rounded-full"/></div>{[['Last backup','Today, 02:00 AM'],['Storage used','2.4 GB of 10 GB'],['Active sessions','11 users online']].map(x=><div className="flex justify-between text-sm border-b border-slate-100 pb-3" key={x[0]}><span className="text-slate-500">{x[0]}</span><b>{x[1]}</b></div>)}</div></Panel></div></>}
function UsersPage({showToast}:{showToast:(s:string)=>void}){const [users]=useState([['Dr. Anita Rao','anita••@wellcare.com','Admin','Active'],['Dr. Suresh Kumar','suresh••@wellcare.com','Pharmacist','Active'],['Dr. Neha Menon','neha••@wellcare.com','Pharmacist','Active'],['Rahul Verma','rahul••@wellcare.com','Pharmacist','Invited'],['Priya Nair','priya••@wellcare.com','Admin','Active']]);return <><PageHeader eyebrow="Administration" title="Users" description="Manage access for your pharmacy team." action={<button className="btn-primary" onClick={()=>showToast('Invite form is ready to use')}><Plus size={16}/> Invite user</button>}/><Panel title="Team members" action={<span className="text-xs text-slate-400">18 total users</span>}><div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-slate-50"><tr>{['User','Role','Status','Last active',''].map(x=><th key={x} className="px-5 py-3 text-[11px] uppercase tracking-wider text-slate-400">{x}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{users.map((u,i)=><tr key={u[1]}><td className="px-5 py-4 flex items-center gap-3"><div className="w-8 h-8 rounded-full bg-brand-50 text-brand-700 flex items-center justify-center text-xs font-bold">{u[0].split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><p className="text-sm font-semibold">{u[0]}</p><p className="text-xs text-slate-400">{u[1]}</p></div></td><td className="px-5 py-4"><span className="chip bg-slate-100 text-slate-600">{u[2]}</span></td><td className="px-5 py-4"><Badge status={u[3]}/></td><td className="px-5 py-4 text-sm text-slate-500">{i===3?'Never':'Today, 10:24 AM'}</td><td className="px-5 py-4 text-right"><button className="btn-ghost p-1.5"><MoreHorizontal size={17}/></button></td></tr>)}</tbody></table></div></Panel></>}
function SystemAudit(){return <><PageHeader eyebrow="Administration" title="System audit" description="A complete timeline of changes across your workspace." action={<button className="btn-secondary"><Download size={15}/> Export log</button>}/><div className="card p-6 max-w-4xl"><div className="space-y-7"><SystemItem icon={UserCheck} title="User role updated" detail="Dr. Anita Rao changed Priya Nair's role from Pharmacist to Admin." who="Dr. Anita Rao" time="Today, 09:42 AM"/><SystemItem icon={PackagePlus} title="Stock added" detail="180 units of Vitamin D3 60K added to batch VD102." who="Dr. Suresh Kumar" time="Today, 08:55 AM"/><SystemItem icon={ShieldCheck} title="Batch blocked" detail="Batch AMX204 was marked as recalled and blocked for dispensing." who="Dr. Anita Rao" time="Yesterday, 04:28 PM"/><SystemItem icon={SettingsIcon} title="Settings changed" detail="Expiry alert threshold was updated from 30 to 45 days." who="Admin" time="Aug 18, 03:20 PM"/><SystemItem icon={Download} title="Report exported" detail="Monthly dispensing audit report was downloaded." who="Dr. Anita Rao" time="Aug 18, 11:04 AM"/></div></div></>}
function SystemItem({icon:Icon,title,detail,who,time}:{icon:React.ComponentType<{size?:number|string}>;title:string;detail:string;who:string;time:string}){return <div className="flex gap-4"><div className="w-9 h-9 rounded-lg bg-slate-100 text-slate-600 flex items-center justify-center shrink-0"><Icon size={17}/></div><div className="flex-1"><div className="flex flex-col sm:flex-row sm:justify-between gap-1"><p className="text-sm font-semibold">{title}</p><span className="text-xs text-slate-400">{time}</span></div><p className="text-sm text-slate-500 mt-1 leading-6">{detail}</p><p className="text-xs text-slate-400 mt-2">By {who}</p></div></div>}
function Detail({label,value}:{label:string;value:string}){return <div><p className="text-xs text-slate-400">{label}</p><p className="text-sm font-semibold mt-1">{value}</p></div>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="fixed inset-0 z-50 flex items-center justify-center p-4"><div className="absolute inset-0 bg-slate-900/40" onClick={onClose}/><div className="relative bg-white rounded-2xl shadow-pop w-full max-w-lg animate-slide-up"><div className="flex items-center justify-between px-6 py-4 border-b border-slate-100"><h3 className="font-semibold">{title}</h3><button className="btn-ghost p-1.5" onClick={onClose}><X size={17}/></button></div><div className="p-6">{children}</div></div></div>}
function Drawer({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="fixed inset-0 z-50"><div className="absolute inset-0 bg-slate-900/30" onClick={onClose}/><div className="absolute right-0 inset-y-0 w-full max-w-md bg-white shadow-pop animate-slide-in-right"><div className="h-20 px-6 border-b border-slate-100 flex items-center justify-between"><h3 className="font-semibold">{title}</h3><button className="btn-ghost p-1.5" onClick={onClose}><X size={18}/></button></div><div className="p-6">{children}</div></div></div>}

export default App;


